<?php
require __DIR__ . '/../app/bootstrap.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); $post = false;
try { if ($id && $id > 0) { $q = db()->prepare('SELECT * FROM posts WHERE id=? AND published=1'); $q->execute([$id]); $post = $q->fetch(); } }
catch (PDOException $ex) { http_response_code(503); exit('Chưa thể tải bài viết. Vui lòng thử lại sau.'); }
if (!$post) http_response_code(404);
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><?php if ($post) { seo($post['title'].' — Xoè 2026',$post['excerpt'],'post.php?id='.(int)$post['id'],$post['image'],'article'); json_ld(['@context'=>'https://schema.org','@type'=>'BlogPosting','headline'=>$post['title'],'description'=>$post['excerpt'],'image'=>site_url($post['image']),'datePublished'=>(new DateTimeImmutable($post['created_at']))->format('c'),'dateModified'=>(new DateTimeImmutable($post['updated_at']))->format('c'),'mainEntityOfPage'=>site_url('post.php?id='.(int)$post['id']),'author'=>['@type'=>'Organization','name'=>'Xoè 2026']]); } else { echo '<title>Không tìm thấy bài viết</title><meta name="robots" content="noindex">'; } ?><link rel="stylesheet" href="<?= asset_url('assets/style.css') ?>"><script src="<?= asset_url('assets/app.js') ?>" defer></script></head><body><?php site_header(); ?><main class="article-page" id="noi-dung"><a class="back" href="<?= e(site_path('posts.php')) ?>">← Trở về câu chuyện và bài viết</a><?php if ($post): ?><p class="eyebrow" style="margin-top:35px">XOÈ 2026 · <?= e(date('d.m.Y', strtotime($post['created_at']))) ?></p><h1><?= e($post['title']) ?></h1><p class="lead"><?= e($post['excerpt']) ?></p><?= image_tag($post['image'],$post['title'],'fetchpriority="high"','100vw') ?><div class="article-body rich-article"><?= post_body($post) ?></div><?php else: ?><h1>Không tìm thấy bài viết.</h1><p>Bài viết chưa được xuất bản hoặc đã được gỡ.</p><?php endif; ?></main><?php site_footer(); ?></body></html>
